/* Page interaction. One concern: putting numbers and charts into the document.
 *
 * chart.js turns data into SVG and touches nothing; this file is the only place
 * that reads STORY_DATA and writes to the page. Keeping the split means a chart
 * can be tested by looking at the string it returns, and a layout change never
 * risks altering a number.
 *
 * Every value written here comes from STORY_DATA, which is generated by
 * src/analysis/24_web_export.py from the tables in outputs/tables. Nothing on
 * this page is typed by hand, so a data refresh updates the prose as well as
 * the charts.
 */

(function () {
  "use strict";

  const data = typeof STORY_DATA !== "undefined" ? STORY_DATA : null;

  function money(value) {
    return "$" + Math.round(value).toLocaleString("en-CA");
  }

  function moneyShort(value) {
    if (value >= 1000000) return "$" + (value / 1000000).toFixed(1) + "m";
    if (value >= 1000) return "$" + Math.round(value / 1000) + "k";
    return "$" + Math.round(value);
  }

  function percent(value) {
    return Math.round(value * 100) + "%";
  }

  function setText(id, text) {
    const node = document.getElementById(id);
    if (node) node.textContent = text;
  }

  function setHtml(id, html) {
    const node = document.getElementById(id);
    if (node) node.innerHTML = html;
  }

  function fail(message) {
    const main = document.querySelector(".page");
    if (!main) return;
    const warning = document.createElement("p");
    warning.className = "caveat";
    warning.textContent = message;
    main.prepend(warning);
  }

  /* ----------------------------------------------------------------- */

  function renderHeadline() {
    const h = data.headline;
    setText("stat-buy", moneyShort(h.buy));
    setText("stat-units", Math.round(h.units).toLocaleString("en-CA"));
    setText(
      "stat-january",
      percent(h.januaryShareLow) + " to " + percent(h.januaryShareHigh)
    );
    setText("stat-order-by", h.orderBy);

    setText("headline-buy", money(h.buy));
    setText("headline-range-low", money(h.rangeLow));
    setText("headline-range-high", money(h.rangeHigh));
    setText("headline-january-low", percent(h.januaryShareLow));
    setText("headline-january-high", percent(h.januaryShareHigh));
    setText("headline-order-by", h.orderBy);
    setText("meta-generated", data.generated);
    setText("meta-premiere", data.premiere);
  }

  function renderSeasonality() {
    const s = data.seasonality;

    setText("seasonality-peak", String(s.categoryPeak));
    setText("seasonality-january", String(s.categoryJanuary));
    setText("seasonality-swing", String(s.attentionSwing));

    const svg = CHART.lineChart({
      categories: s.months,
      ariaLabel:
        "Monthly seasonal index. The book and hobby category peaks in December " +
        "at " + s.categoryPeak + " and falls to " + s.categoryJanuary +
        " in January, while franchise attention stays near 100 all year.",
      band: { from: 10, to: 11, label: "gift buying" },
      formatY: function (v) {
        return String(Math.round(v));
      },
      series: [
        {
          values: s.category,
          className: "chart__line--category",
          dotClassName: "chart__dot--category"
        },
        {
          values: s.attention,
          className: "chart__line--attention",
          dotClassName: "chart__dot--attention"
        },
        { values: s.allRetail, className: "chart__line--all-retail" }
      ]
    });

    setHtml("chart-seasonality", svg);
    setHtml(
      "legend-seasonality",
      CHART.legend([
        { label: "Book and hobby retail (459A)", swatchClass: "legend__swatch--category" },
        { label: "Franchise attention", swatchClass: "legend__swatch--attention" },
        { label: "All Canadian retail", swatchClass: "legend__swatch--all-retail" }
      ])
    );
  }

  function renderDemandProfile() {
    const d = data.demandProfile;

    const svg = CHART.groupedBarChart({
      categories: d.months,
      ariaLabel:
        "Monthly category sales from November 2026 to March 2027 under the low, " +
        "central and high scenarios, against a no-premiere baseline.",
      formatY: moneyShort,
      marker: { afterIndex: 1, label: "premiere" },
      baseline: { values: d.baseline },
      groups: [
        { values: d.low, className: "chart__bar--baseline" },
        { values: d.central, className: "chart__bar--central" },
        { values: d.high, className: "chart__bar--baseline" }
      ]
    });

    setHtml("chart-demand", svg);
    setHtml(
      "legend-demand",
      CHART.legend([
        { label: "Central scenario", swatchClass: "legend__swatch--central" },
        { label: "Low and high scenarios", swatchClass: "legend__swatch--baseline" },
        { label: "Baseline, no premiere", swatchClass: "legend__swatch--all-retail" }
      ])
    );
  }

  function renderTradeoff() {
    const rows = data.tradeoff;
    const values = rows.map(function (r) {
      return r.expected_profit_cad;
    });
    let bestIndex = 0;
    values.forEach(function (v, i) {
      if (v > values[bestIndex]) bestIndex = i;
    });

    const svg = CHART.barChart({
      categories: rows.map(function (r) {
        return percent(r.january_reserve_proportion);
      }),
      values: values,
      highlightIndex: bestIndex,
      formatY: moneyShort,
      ariaLabel:
        "Expected profit against the share of the buy held for the January " +
        "position. It peaks at " +
        percent(rows[bestIndex].january_reserve_proportion) + "."
    });

    setHtml("chart-tradeoff", svg);
    setText("tradeoff-best", percent(rows[bestIndex].january_reserve_proportion));
  }

  function renderForecastTable() {
    const f = data.forecast;
    setText("forecast-best-model", f.bestModel);
    setText("forecast-best-mape", f.bestMape + "%");
    setText("forecast-baseline-mape", f.baselineMape + "%");

    const body = f.models
      .map(function (m) {
        const isBest = m.model === f.bestModel;
        return (
          '<tr class="' + (isBest ? "is-highlighted" : "") + '"><td>' +
          m.model + '</td><td class="numeric">' + m.mape.toFixed(1) +
          '</td><td class="numeric">' + Math.round(m.mae).toLocaleString("en-CA") +
          "</td></tr>"
        );
      })
      .join("");
    setHtml("table-forecast-body", body);
  }

  function renderOrderSchedule() {
    const body = data.orderSchedule
      .map(function (row) {
        const late = row.already_late === true || row.already_late === "True";
        return (
          "<tr><td>" + row.position + "</td><td>" + row.product_type +
          '</td><td class="numeric">' + row.lead_time_days + "</td><td>" +
          row.order_by + "</td><td>" +
          (late ? '<span class="flag--late">already passed</span>' : "on time") +
          "</td></tr>"
        );
      })
      .join("");
    setHtml("table-schedule-body", body);

    const lateCount = data.orderSchedule.filter(function (r) {
      return r.already_late === true || r.already_late === "True";
    }).length;
    setText("schedule-late-count", String(lateCount));
  }

  function renderSensitivity() {
    const rows = data.sensitivity;
    const body = rows
      .map(function (r) {
        const isDefault =
          Math.abs(r.attention_pass_through - data.assumptions.passThrough) < 1e-9;
        return (
          '<tr class="' + (isDefault ? "is-highlighted" : "") + '"><td>' +
          percent(r.attention_pass_through) + '</td><td class="numeric">' +
          money(r.season_sales_central_cad) + "</td></tr>"
        );
      })
      .join("");
    setHtml("table-sensitivity-body", body);
    setText("sensitivity-low", money(rows[0].season_sales_central_cad));
    setText("sensitivity-high", money(rows[rows.length - 1].season_sales_central_cad));
    setText("sensitivity-assumption", percent(data.assumptions.passThrough));
  }

  function renderEvents() {
    const body = data.events
      .map(function (row) {
        const step = row.step_multiple === null || row.step_multiple === undefined
          ? "n/a"
          : Number(row.step_multiple).toFixed(2) + "x";
        return (
          "<tr><td>" + row.event + '</td><td class="numeric">' +
          Number(row.peak_multiple).toFixed(2) + 'x</td><td class="numeric">' +
          row.days_to_settle + '</td><td class="numeric">' + step + "</td></tr>"
        );
      })
      .join("");
    setHtml("table-events-body", body);
  }

  function render() {
    if (!data) {
      fail(
        "The data file did not load. Check that web/js/data.js exists; " +
        "regenerate it with python src/analysis/24_web_export.py."
      );
      return;
    }
    renderHeadline();
    renderSeasonality();
    renderDemandProfile();
    renderTradeoff();
    renderForecastTable();
    renderOrderSchedule();
    renderSensitivity();
    renderEvents();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", render);
  } else {
    render();
  }
})();
